import{_ as a,o as t,c as e,a3 as o}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"尾声","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/108-尾声.md","filePath":"books/attached/108-尾声.md","lastUpdated":1794316978000}'),_={name:"books/attached/108-尾声.md"};function l(r,p,i,s,d,n){return t(),e("div",null,[...p[0]||(p[0]=[o('<h1 id="尾声" tabindex="-1">尾声 <a class="header-anchor" href="#尾声" aria-label="Permalink to &quot;尾声&quot;">​</a></h1><p>对于我们来说，从这本书上所得到的一条最重要信息就是：亲密关系并不完全是听天由命的。亲密关系是人们的一切经历中，最大的财富之一，其价值要甚于生命的其他馈赠。事实上，一项研究表明，来自三百余所大学的学生被试中，有75%的人表示为了一段浪漫的恋情，愿意牺牲自己所追逐的目标。但即使我们在亲密关系上倾注了良苦用心，却还是对亲密关系背后的科学知之甚少，常常让自己盲从于一些传言或是错误的观念里。</p><p>即使是对成人依恋风格背后的科学进行了透彻学习的我们俩，在听到某些恋情故事，看到爱情电影勾起旧时回忆的时候，都会不时地陷入类似的思维定式之中。近来我们在看一部男孩女孩邂逅主题的电影时，就产生了这种情形。电影是说一个年轻人疯狂爱上了一位漂亮又知性的女孩。他爱到迷乱，只想与女孩共度余生。而女孩，却一心追求自由自在，无拘无束的生活——并且从一开始就告诉了男孩这一点。整个故事中，女孩子都在传递模棱两可的信息，她一直在与他周旋，让他对于两人的美好结局抱着不切实际的幻想。而结局却是非好莱坞典型式的，她最终伤了她的心。故事的最后，他得知女孩与心仪的人成婚，并过得十分幸福。（总之电影止步于此，算是所有人认知中的最好结果了，无论对于年轻人，还是对于屏幕前的我们。）</p><p>在看到电影的时候，我们俩的反应和其他观众一样，一眼就爱上了那个女主角。她身形健美，充满热情又十分独立——是真正热爱自由的灵魂。同时她还十分坦诚，预先如实告诉他，自己并不追求一段严肃的亲密关系。因此我们也不会因此而责难她，毕竟，他显然不是她“生命中那个唯一”。（况且，最后电影也告诉我们，她找到了真正的“唯一”。）电影演到大半，我们都陷入一种浪漫的可能性中，认为女孩终究会向男孩敞开心扉，让他赢取芳心。虽然电影一开始就有所剧透，表示这并不是一部爱情片，但我们仍然没有放弃对于两位明星携手看夕阳这种场景的幻想。</p><p>然而细细一想，我们很快就能发现自己陷入了一个非常常见的亲密关系误区。即使是深谙恋爱行为背后逻辑，具有专业素养的我们，仍旧落入了老旧且无用的观念中。我们仍然任由那些根深蒂固的误区影响着自己。</p><p>首要的误区就是：每个人都有相等的亲密需求量。我们仍然坚信着每个人都会深深爱上他人（到这里或许还说得过去），不仅如此，一旦爱上别人，他们还可能将自己完全改造成另一个人（这里就显然不太对了）。不管他们之前是什么样的，一旦他们找到了那个“唯一”，就极其可能成为一位隐忍、忠诚、乐于支持的伴侣——总之对亲密关系全情投入。我们很容易忘记一点——事实上每个人对亲密的需求都是不一样的。当一个人对亲密的追求，遭遇另一个人对独立和距离的渴望，就会产生很多的不幸。在对这一点有所认识以后，你才会在择偶的时候找对路子，找到一个亲密需求与你契合的人（若你是单身），或者对于现有的关系中需求的差异，有一个全新的认识——总之最初也是最必要的一点，就是让关系转向一个更加安全的方向。</p><p>而第二个公认的误区就是，我们沦为了“婚姻必须从一而终”这个观念的奴隶。浪漫故事或许会止于婚姻，我们也很容易相信，人一旦结了婚，爱的力量就将坚不可摧，一旦决定结婚，就决定了两人已经准备好了成为真正的亲密伴侣，情感上也密不可分。我们很不能认同有的伴侣在走入婚姻殿堂的时候，并没有抱着这样的态度，或者说没有能力去实现这些。我们所坚信的，与我们对电影结局的希求一样，每个人都能够改变，并且对伴侣完全忠诚（特别是在两人都深爱着对方的情况下）。</p><p>然而在这本书中，我们向大家阐明了一点：不匹配的依恋风格会在婚姻中产生多么巨大的不幸，即使是两人都深爱着对方。若是你处于这种关系里，根本不必因为无能或不满的感受而心生愧疚。毕竟，你最基本的需求都不一定得到满足，而亲密关系的运作显然不能单单靠爱情。若是你读完此书，基于依恋风格来区分彼此，你就会从另一个全新的角度来看待和处理这个问题。</p><p>而我们落入的第三个不得不提的误区在于：我们需要为自己的需求负责，但伴侣没有义务为我们的需求负责。当潜在的伴侣在亲密关系伊始，就向我们发出“米兰达警告”，宣读“我们的权利”（详见第11章）时，告诉我们对方没有准备好做出承诺，因此也不愿对我们的幸福负责；或者在没有考虑到我们需求的前提下，就单方面宣布两人的长久关系，事实上，我们完全有可能会迅速接受之。其中逻辑对于人们来说是理所当然的，我们的朋友可能会劝解：“人家都提前跟你说了不会负责”或者“他们一直在表示对于这个问题的强烈感受，所以这事只能怪你自己”。而当我们陷入爱情，非常想要继续一段感情的时候，其实是会自动忽略我们所收到的抗辩信息的。我们或许不会立马认识到，那些置我们情感于不顾的人或许不会是好的伴侣，反而会接纳对方的态度。因此，我们要不断提醒自己：真正的伴侣关系，是两人都认为自己有义务顾及对方的情绪，为对方的幸福负责。</p><p>而当我们抛却这些错觉之后，这部电影和生活中的很多场景，都将一并产生非常不同的意义。这个故事线将脱去神话般的外衣，变得更合乎情理。它将不再是男孩遇见女孩的故事，而变成焦虑型的人遇见回避型伴侣故事；他追逐亲密，而她避之不及。作者从一开始就设计好这一切，可电影的男主角却全然不知道。他爱着的那个女孩即使后来嫁给了别人，也不会改变她是个回避型依恋风格的事实，她或者她丈夫今后的婚姻生活是否幸福美满也未成定数。也有可能她继续我行我素，在诸多方面也拒丈夫于千里之外。甚至如我们所想，这男主角可能会成为她恋恋不舍的“幽灵般”的前任。</p><p>这部电影让我们认识到，在生活中，我们很难把根深蒂固的观念给抹去——即使他们毫无用途。但将这些观念抛却，又是十分必要的，继续秉持着它们是非常危险的。这些谬误让我们忽视自己的基本需要，丧失自我，让自己的自尊和幸福都成为牺牲品。</p><p>我们坚信，每个人都想从安全型情感纽带中获得裨益。当伴侣的行为满足于我们安全基地的情感需求，我们便获得更多鼓励，更强力量投身于世界当中，更加坚定地做自己。对方是我们成为最好自己的坚强后盾，而我们之于对方，也同样如此。</p><p>我们一定要记住下面几条：</p><ul><li><p>你的亲密需求是合理的。</p></li><li><p>不要因为自己依赖亲密的人而感到不安——这是你的基因使然。</p></li><li><p>从依恋理论的视角来看，一段关系应该让你变得更加自信，给予你内心的宁静。如果并没有的话，你就应该警醒起来了！</p></li><li><p>最重要的是，一定要保持真实的自己——玩一些感情把戏，只会让你距离终极的幸福目标越来越远，同时也会让你错过真正对的人。</p></li></ul><p>我们希望你能将本书中凝聚的智慧学以致用，帮助你在恋情中寻得幸福，也能在生活中任意方面都游刃有余，这毕竟是我们二十余年的研究成果。通过本书中强调的依恋原则，你可以找到更加真挚完美的爱情，并且令其长久，而非让生命中如此重要的一个部分错失良机！</p>',15)])])}const m=a(_,[["render",l]]);export{h as __pageData,m as default};
